15	// Deferred SDK builtins that either sidestep nanoclaw's own scheduling or
16	// don't fit our async message-passing model (they're designed for Claude
17	// Code's interactive UI and would hang here).
18	//
19	// - CronCreate / CronDelete / CronList / ScheduleWakeup: we have durable
20	//   scheduling via mcp__nanoclaw__schedule_task.
21	// - AskUserQuestion: SDK returns a placeholder instead of blocking on a
22	//   real answer — we have mcp__nanoclaw__ask_user_question that persists
23	//   the question and blocks on the real reply.
24	// - EnterPlanMode / ExitPlanMode / EnterWorktree / ExitWorktree: Claude
25	//   Code UI affordances; in a headless container they'd appear stuck.
26	const SDK_DISALLOWED_TOOLS = [
27	  'CronCreate',
28	  'CronDelete',
29	  'CronList',
30	  'ScheduleWakeup',
31	  'AskUserQuestion',
32	  'EnterPlanMode',
33	  'ExitPlanMode',
34	  'EnterWorktree',
35	  'ExitWorktree',
36	];
