38	// Tool allowlist for NanoClaw agent containers. MCP-tool entries are derived
39	// at the call site from the registered `mcpServers` map so that any server
40	// added via `add_mcp_server` (or wired in container.json directly) is
41	// reachable to the agent — without this, the SDK's allowedTools filter
42	// silently drops every MCP namespace not listed here.
43	const TOOL_ALLOWLIST = [
44	  'Bash',
45	  'Read',
46	  'Write',
47	  'Edit',
48	  'Glob',
49	  'Grep',
50	  'WebSearch',
51	  'WebFetch',
52	  'Task',
53	  'TaskOutput',
54	  'TaskStop',
55	  'TeamCreate',
56	  'TeamDelete',
57	  'SendMessage',
58	  'TodoWrite',
59	  'ToolSearch',
60	  'Skill',
61	  'NotebookEdit',
62	];
