64	// MCP server names are sanitized by the SDK when forming tool prefixes:
65	// any character outside [A-Za-z0-9_-] becomes '_'. Mirror that here so our
66	// allowlist patterns match what the SDK actually exposes.
67	function mcpAllowPattern(serverName: string): string {
68	  return `mcp__${serverName.replace(/[^a-zA-Z0-9_-]/g, '_')}__*`;
69	}
