78	/**
79	 * Push-based async iterable for streaming user messages to the Claude SDK.
80	 */
81	class MessageStream {
82	  private queue: SDKUserMessage[] = [];
83	  private waiting: (() => void) | null = null;
84	  private done = false;
85	
86	  push(text: string): void {
87	    this.queue.push({
88	      type: 'user',
89	      message: { role: 'user', content: text },
90	      parent_tool_use_id: null,
91	      session_id: '',
92	    });
93	    this.waiting?.();
94	  }
95	
96	  end(): void {
97	    this.done = true;
98	    this.waiting?.();
99	  }
