100	
101	  async *[Symbol.asyncIterator](): AsyncGenerator<SDKUserMessage> {
102	    while (true) {
103	      while (this.queue.length > 0) {
104	        yield this.queue.shift()!;
105	      }
106	      if (this.done) return;
107	      await new Promise<void>((r) => {
108	        this.waiting = r;
109	      });
110	      this.waiting = null;
111	    }
112	  }
113	}
