117	interface ParsedMessage {
118	  role: 'user' | 'assistant';
119	  content: string;
120	}
121	
122	function parseTranscript(content: string): ParsedMessage[] {
123	  const messages: ParsedMessage[] = [];
124	  for (const line of content.split('\n')) {
125	    if (!line.trim()) continue;
126	    try {
127	      const entry = JSON.parse(line);
128	      if (entry.type === 'user' && entry.message?.content) {
129	        const text = typeof entry.message.content === 'string' ? entry.message.content : entry.message.content.map((c: { text?: string }) => c.text || '').join('');
130	        if (text) messages.push({ role: 'user', content: text });
131	      } else if (entry.type === 'assistant' && entry.message?.content) {
132	        const textParts = entry.message.content.filter((c: { type: string }) => c.type === 'text').map((c: { text: string }) => c.text);
133	        const text = textParts.join('');
134	        if (text) messages.push({ role: 'assistant', content: text });
135	      }
136	    } catch {
137	      /* skip unparseable lines */
138	    }
139	  }
140	  return messages;
141	}
