155	/**
156	 * PreToolUse hook: record the current tool + its declared timeout so the host
157	 * sweep can widen its stuck tolerance while Bash is running a long-declared
158	 * script. Defense-in-depth: if SDK_DISALLOWED_TOOLS slips through somehow,
159	 * block the call here instead of letting the agent hang.
160	 */
161	const preToolUseHook: HookCallback = async (input) => {
162	  const i = input as { tool_name?: string; tool_input?: Record<string, unknown> };
163	  const toolName = i.tool_name ?? '';
164	  if (SDK_DISALLOWED_TOOLS.includes(toolName)) {
165	    return {
166	      decision: 'block',
167	      stopReason: `Tool '${toolName}' is not available in this environment — use the nanoclaw equivalent.`,
168	    } as unknown as ReturnType<HookCallback>;
169	  }
170	  // Bash exposes its timeout via the tool_input.timeout field (ms). Any other
171	  // tool: no declared timeout.
172	  const declaredTimeoutMs =
173	    toolName === 'Bash' && typeof i.tool_input?.timeout === 'number' ? (i.tool_input.timeout as number) : null;
174	  try {
175	    setContainerToolInFlight(toolName, declaredTimeoutMs);
176	  } catch (err) {
177	    log(`PreToolUse: failed to record container_state: ${err instanceof Error ? err.message : String(err)}`);
178	  }
179	  return { continue: true };
180	};
