236	function createPreCompactHook(assistantName?: string): HookCallback {
237	  return async (input) => {
238	    const preCompact = input as PreCompactHookInput;
239	    archiveTranscriptFile(preCompact.transcript_path, preCompact.session_id, assistantName);
240	    return {};
241	  };
242	}
