293	/** Epoch-ms of the first transcript entry, or null if unreadable. */
294	function transcriptStartMs(transcriptPath: string): number | null {
295	  try {
296	    const fd = fs.openSync(transcriptPath, 'r');
297	    try {
298	      const buf = Buffer.alloc(4096);
299	      const n = fs.readSync(fd, buf, 0, buf.length, 0);
300	      const firstLine = buf.toString('utf-8', 0, n).split('\n', 1)[0];
301	      const ts = JSON.parse(firstLine)?.timestamp;
302	      const ms = ts ? Date.parse(ts) : NaN;
303	      return Number.isNaN(ms) ? null : ms;
304	    } finally {
305	      fs.closeSync(fd);
306	    }
307	  } catch {
308	    return null;
309	  }
310	}
