314	/**
315	 * Claude Code auto-compacts context at this window (tokens). Kept here so
316	 * the generic bootstrap doesn't need to know about Claude-specific env vars.
317	 *
318	 * Operator override: set CLAUDE_CODE_AUTO_COMPACT_WINDOW in the host env to
319	 * raise or lower the threshold without editing source — useful when running
320	 * with a 1M-context model variant or when emergency-tuning a deployment.
321	 */
322	const CLAUDE_CODE_AUTO_COMPACT_WINDOW = process.env.CLAUDE_CODE_AUTO_COMPACT_WINDOW || '165000';
