324	/**
325	 * Stale-session detection. Matches Claude Code's error text when a
326	 * resumed session can't be found — missing transcript .jsonl, unknown
327	 * session ID, etc.
328	 */
329	const STALE_SESSION_RE = /no conversation found|ENOENT.*\.jsonl|session.*not found/i;
