331	export class ClaudeProvider implements AgentProvider {
332	  readonly supportsNativeSlashCommands = true;
333	
334	  private assistantName?: string;
335	  private mcpServers: Record<string, McpServerConfig>;
336	  private env: Record<string, string | undefined>;
337	  private additionalDirectories?: string[];
338	  private model?: string;
339	  private effort?: string;
340	
341	  constructor(options: ProviderOptions = {}) {
342	    this.assistantName = options.assistantName;
343	    this.mcpServers = options.mcpServers ?? {};
344	    this.additionalDirectories = options.additionalDirectories;
345	    this.model = options.model;
346	    this.effort = options.effort;
347	    this.env = {
348	      ...(options.env ?? {}),
349	      CLAUDE_CODE_AUTO_COMPACT_WINDOW,
350	    };
351	  }
352	
353	  isSessionInvalid(err: unknown): boolean {
354	    const msg = err instanceof Error ? err.message : String(err);
355	    return STALE_SESSION_RE.test(msg);
356	  }
357	
358	  maybeRotateContinuation(continuation: string): string | null {
359	    const transcriptPath = findTranscriptPath(continuation);
360	    if (!transcriptPath) return null;
361	
362	    let size: number;
363	    try {
364	      size = fs.statSync(transcriptPath).size;
365	    } catch {
366	      return null;
367	    }
368	
369	    const maxBytes = transcriptRotateBytes();
370	    const startMs = transcriptStartMs(transcriptPath);
371	    const ageMs = startMs === null ? 0 : Date.now() - startMs;
372	    const maxAgeMs = transcriptRotateAgeMs();
373	
374	    let reason: string | null = null;
375	    if (size > maxBytes) {
376	      reason = `transcript ${(size / 1_048_576).toFixed(1)}MB > ${(maxBytes / 1_048_576).toFixed(0)}MB cap`;
377	    } else if (startMs !== null && ageMs > maxAgeMs) {
378	      reason = `transcript ${(ageMs / 86_400_000).toFixed(1)}d old > ${(maxAgeMs / 86_400_000).toFixed(0)}d cap`;
379	    }
380	    if (!reason) return null;
381	
382	    // Preserve a readable summary, then move the heavy .jsonl out of the
383	    // resume path so the SDK starts a fresh session and the disk is reclaimed.
384	    archiveTranscriptFile(transcriptPath, continuation, this.assistantName);
385	    try {
386	      fs.renameSync(transcriptPath, `${transcriptPath}.rotated-${Date.now()}`);
387	    } catch (err) {
388	      log(`Failed to move rotated transcript aside: ${err instanceof Error ? err.message : String(err)}`);
389	    }
390	    return reason;
391	  }
