1	/**
2	 * NanoClaw Agent Runner v2
3	 *
4	 * Runs inside a container. All IO goes through the session DB.
5	 * No stdin, no stdout markers, no IPC files.
6	 *
7	 * Config is read from /workspace/agent/container.json (mounted RO).
8	 * Only TZ and OneCLI networking vars come from env.
9	 *
10	 * Mount structure:
11	 *   /workspace/
12	 *     inbound.db        ← host-owned session DB (container reads only)
13	 *     outbound.db       ← container-owned session DB
14	 *     .heartbeat        ← container touches for liveness detection
15	 *     outbox/           ← outbound files
16	 *     agent/            ← agent group folder (CLAUDE.md, container.json, working files)
17	 *       container.json  ← per-group config (RO nested mount)
18	 *     global/           ← shared global memory (RO)
19	 *   /app/src/           ← shared agent-runner source (RO)
20	 *   /app/skills/        ← shared skills (RO)
21	 *   /home/node/.claude/ ← Claude SDK state + skill symlinks (RW)
22	 */
23	
24	import fs from 'fs';
25	import path from 'path';
26	import { fileURLToPath } from 'url';
27	
28	import { loadConfig } from './config.js';
29	import { buildSystemPromptAddendum } from './destinations.js';
30	// Providers barrel — each enabled provider self-registers on import.
31	// Provider skills append imports to providers/index.ts.
32	import './providers/index.js';
33	import { createProvider, type ProviderName } from './providers/factory.js';
34	import { runPollLoop } from './poll-loop.js';
35	
36	function log(msg: string): void {
37	  console.error(`[agent-runner] ${msg}`);
38	}
